import argparse,json
ap=argparse.ArgumentParser()
ap.add_argument('--repo',type=Path,default=Path(__file__).resolve().parents[2])
a=ap.parse_args();r=a.repo.resolve()
data=json.loads((r/'experiments/main-scout20/results.json').read_text())
html='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="icon" href="data:,"><title>20문제 Scout → Merger 실행 결과</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7f8;color:#18332f;font:15px/1.65 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:32px 24px}a{color:#087f5b}h1{font-size:30px;line-height:1.3;margin:14px 0}h2{margin:0;font-size:19px}.sub{color:#58716b}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:24px 0}.stat,article{background:white;border:1px solid #dbe5e1;border-radius:14px;padding:20px}.stat strong{display:block;font-size:30px}.note{padding:16px 20px;border-left:4px solid #0a8364;background:#e7f2ed}nav{display:flex;gap:20px;align-items:center;flex-wrap:wrap;margin:22px 0}select{font:inherit;padding:8px;border:1px solid #c5d5ce;border-radius:6px;background:white}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}article p{margin:4px 0}article .name{font-size:12px;color:#58716b;overflow-wrap:anywhere}svg{width:100%;height:auto;display:block}.legend{display:flex;gap:14px;flex-wrap:wrap;font-size:13px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:5px}.score{float:right;font-size:23px;font-weight:700}.foot{font-size:13px;color:#58716b}table{border-collapse:collapse;width:100%;margin-top:15px}td,th{padding:7px;border-bottom:1px solid #e3ebe7;text-align:right}td:first-child,th:first-child{text-align:left}@media(max-width:720px){main{padding:20px 12px}.stats{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}h1{font-size:24px}.stat{padding:12px}.stat strong{font-size:26px}}
</style></head><body><main><a href="/">← 60문제 대시보드</a><p class="sub">Strata F001–F010 · LeanPool F041–F050</p><h1>Scout → Merger, 20문제 실행 결과</h1><p>제출할 하네스의 성능은 <strong>단일 실행 평균</strong>으로 비교합니다. 최고 기록 집계는 풀이 보관용입니다.</p><div class="stats"><div class="stat">이번 하네스 단독<strong>75.12점</strong><small>이전 실행 74.12점</small></div><div class="stat">최고 기록 집계<strong>76.86점</strong><small>기존 74.47점 · 8문제 교체</small></div><div class="stat">총 정산 비용<strong>$44.81</strong><small>초기 오류 실행 $5.15 포함</small></div><div class="stat">최종 검증<strong>20 / 20</strong><small>40회 완료 10 · 예산 종료 10</small></div></div>
<p class="note">예산 $3/문제 · Scout 6+6+6, Merger 22회 평가. PR #67의 예산 소진까지 Merger 반복 옵션은 꺼져 있습니다. PR #69 비교 실험은 별도입니다. 이번 실행은 초기 오류 호출 비용을 3문제 예산에서 차감했으므로 이전 실행과 완전히 같은 조건의 대조 실험이 아닙니다.</p>
<h2>어느 단계에서 개선됐나</h2><div id="stages"></div><p class="foot">개선량은 기본 버전에서 관측된 최고 후보 점수 상승분입니다. 먼저 실행되는 Scout A의 이점이 포함되므로 단계의 독립적인 효과로 해석할 수 없습니다.</p>
<nav><label>가로축 <select id="axis"><option value="step">API 호출 순서</option><option value="cost">누적 API 비용</option></select></label><label>문제 <select id="problem"><option value="all">전체 20문제</option></select></label><a href="scout20.json" download>결과 JSON</a></nav><div class="legend"><span><i class="dot" style="background:#4986b8"></i>Scout A</span><span><i class="dot" style="background:#9465b5"></i>Scout B</span><span><i class="dot" style="background:#bf8634"></i>Scout C</span><span><i class="dot" style="background:#087f5b"></i>Merger</span></div><p class="foot">선: 호출별 최고 후보 · 점: 유효 후보 · 검은 마름모: 최종 확정 점수. 검색 호출도 가로축에 포함됩니다. 탐색 점수는 기본 버전 잠정값이며, 최종 점수만 지정 버전 전체 통과 및 새로운 HB 3회 측정을 완료했습니다. 점에 마우스를 올리면 상세값을 볼 수 있습니다.</p><div class="grid" id="charts"></div><p class="foot">공식 서버 채점 결과 아님. 점수 = 100 − (100/3) × (후보 Length/원본 Length + 후보 HB/원본 HB). 동일 풀이에 짝지어진 원본 기준값 사용. 비용은 제공자 응답 토큰 사용량 × 고정 단가이며 청구서 대조 전입니다.</p></main><script id="data" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('data').textContent), ns='http://www.w3.org/2000/svg', colors={'scout-a':'#4986b8','scout-b':'#9465b5','scout-c':'#bf8634',merge:'#087f5b'};
const stages=document.getElementById('stages');let table=document.createElement('table');table.innerHTML='<thead><tr><th>단계</th><th>API 호출</th><th>후보 평가</th><th>유효 후보</th><th>평가 중 유효율</th></tr></thead>';let tb=document.createElement('tbody');for(const [key,v] of Object.entries(data.stages)){let tr=document.createElement('tr');for(const x of [key,v.calls,v.evaluated,v.valid,(100*v.valid/v.evaluated).toFixed(1)+'%']){let td=document.createElement('td');td.textContent=x;tr.append(td)}tb.append(tr)}table.append(tb);stages.append(table);
for(const p of data.problems){let option=document.createElement('option');option.value=p.row;option.textContent='F'+String(p.row).padStart(3,'0');document.getElementById('problem').append(option)}
function svgEl(name,attrs={},text){let e=document.createElementNS(ns,name);for(const [k,v]of Object.entries(attrs))e.setAttribute(k,v);if(text!==undefined)e.textContent=text;return e}
function render(){const target=document.getElementById('charts');target.replaceChildren();const axis=document.getElementById('axis').value,filter=document.getElementById('problem').value;for(const p of data.problems){if(filter!=='all'&&Number(filter)!==p.row)continue;let card=document.createElement('article'),title=document.createElement('h2');title.textContent='F'+String(p.row).padStart(3,'0');let score=document.createElement('span');score.className='score';score.textContent=p.score.toFixed(2)+'점';title.append(score);card.append(title);let name=document.createElement('p');name.className='name';name.textContent=p.name;card.append(name);let desc=document.createElement('p');desc.textContent=p.evaluations+'회 평가 · '+p.calls+'회 호출 · '+(p.status==='completed'?'40회 완료':'예산 제한 종료');card.append(desc);
const svg=svgEl('svg',{viewBox:'0 0 520 260',role:'img','aria-label':title.textContent+' 호출별 점수 변화'}),last=p.points.at(-1),maxX=axis==='step'?p.calls:Number(last.costUsd),xx=v=>42+448*v/Math.max(maxX,.01),yy=v=>218-1.85*Math.max(0,Math.min(100,v));for(const y of [0,20,40,60,80,100]){svg.append(svgEl('line',{x1:42,x2:490,y1:yy(y),y2:yy(y),stroke:y===60?'#d99191':'#e0e8e5','stroke-dasharray':y===60?'4 4':'0'}));svg.append(svgEl('text',{x:30,y:yy(y)+4,'font-size':11,'text-anchor':'end',fill:'#58716b'},y))}
let line='M '+xx(0)+' '+yy(100/3);for(const t of p.points){const x=xx(axis==='step'?t.step:Number(t.costUsd));line+=' H '+x+' V '+yy(t.bestScore)}svg.append(svgEl('path',{d:line,fill:'none',stroke:'#4c635c','stroke-width':1.7}));for(const t of p.points){if(t.candidateScore===null)continue;let dot=svgEl('circle',{cx:xx(axis==='step'?t.step:Number(t.costUsd)),cy:yy(t.candidateScore),r:3,fill:colors[t.stage]});dot.append(svgEl('title',{},'#'+t.step+' '+t.stage+' · '+t.candidateScore.toFixed(2)+'점 · $'+Number(t.costUsd).toFixed(3)));svg.append(dot)}let finalX=xx(maxX),finalY=yy(p.score);svg.append(svgEl('path',{d:'M '+finalX+' '+(finalY-6)+' l 6 6 -6 6 -6 -6 Z',fill:'#132c25'}));svg.append(svgEl('text',{x:42,y:244,'font-size':11,fill:'#58716b'},'0'));svg.append(svgEl('text',{x:490,y:244,'font-size':11,'text-anchor':'end',fill:'#58716b'},axis==='step'?maxX+'회':'$'+maxX.toFixed(2)));card.append(svg);let foot=document.createElement('p');foot.className='foot';foot.textContent='기존 대시보드 '+p.priorDashboardScore.toFixed(2)+'점 → 이번 단독 '+p.score.toFixed(2)+'점 · 최대 상승 #'+p.largestGain.step+' ('+p.largestGain.stage+', +'+p.largestGain.gain.toFixed(2)+'점)';card.append(foot);target.append(card)}}document.getElementById('axis').addEventListener('change',render);document.getElementById('problem').addEventListener('change',render);render();
</script></body></html>'''
chart={k:v for k,v in data.items() if k in ['stages','problems']};chart['problems']=[{k:v for k,v in p.items() if k not in ['compilerRecords','evidence','versions']} for p in chart['problems']]
(r/'dashboard/public/reports/scout20.html').write_text(html.replace('__DATA__',json.dumps(chart,ensure_ascii=False).replace('</','<\\/')))
